// ============================================================================
// 1. COORDENADAS DAS ZONAS, SNAP POINTS E ÁREAS DOS JOGADORES
// ============================================================================

type Vetor3 = [number, number, number];
type FaseJogo = "FASE_1" | "FASE_2" | "FASE_3" | "FASE_4" | "FASE_5" | "FIM_DE_JOGO";

interface ConfigJogador {
  nome: string;
  nomeSnapAtaque: string;
  centroMao: Vetor3;
  pontoAtaque: Vetor3;
  rotacaoY: number;
}

const POSICOES_BASE: Record<string, Vetor3> = {
  // 3 cartas de Ocorrência:
  Ocorrencia_1: [-0.315, 1.52, 0.181],
  Ocorrencia_2: [0, 1.515, 0.178],
  Ocorrencia_3: [0.308, 1.529, 0.179],

  // 3 Depósitos de Ataque à frente das Ocorrências:
  Deposito_1: [-0.311, 1.522, -0.153],
  Deposito_2: [0, 1.513, -0.157],
  Deposito_3: [0.306, 1.534, -0.147],

  // Pilha de Descarte:
  Zona_Descarte: [0.949, 1.536, 0.093],
};

// Cópia ativa que será automaticamente ajustada aos Snap Points mais próximos
const POSICOES_MESA: Record<string, Vetor3> = { ...POSICOES_BASE };

const ALTURA_MESA = 1.575;
const RAIO_DETECCAO = 0.16;

// Áreas das mãos visíveis e Snap Points de ataque dos 3 jogadores
const JOGADORES_MESA: ConfigJogador[] = [
  {
    nome: "Jogador 1",
    nomeSnapAtaque: "Ataque_1",
    centroMao: [0, ALTURA_MESA, 0.66],
    pontoAtaque: [0, ALTURA_MESA, 0.43],
    rotacaoY: 180,
  },
  {
    nome: "Jogador 2",
    nomeSnapAtaque: "Ataque_2",
    centroMao: [-1.35, ALTURA_MESA, 0.56],
    pontoAtaque: [-1.35, ALTURA_MESA, 0.33],
    rotacaoY: 180,
  },
  {
    nome: "Jogador 3",
    nomeSnapAtaque: "Ataque_3",
    centroMao: [0, ALTURA_MESA, -0.66],
    pontoAtaque: [0, ALTURA_MESA, -0.43],
    rotacaoY: 0,
  },
];

// ============================================================================
// 2. ESTADO DO JOGO
// ============================================================================

interface EstadoJogo {
  jogoIniciado: boolean;
  rodada: number;
  faseAtual: FaseJogo;
  pontuacaoOculta: number;
  cartasAtaqueDaRodada: Set<string>;
  deckAcaoFaceUpBase: boolean;
  snapsAtaqueVinculados: number;
  ultimoTotalSnapsPreenchidos: number;
  posicoesAnteriores: Map<string, Vetor3>;
  ocupado: boolean;
}

const estado: EstadoJogo = {
  jogoIniciado: false,
  rodada: 1,
  faseAtual: "FASE_1",
  pontuacaoOculta: 0,
  cartasAtaqueDaRodada: new Set<string>(),
  deckAcaoFaceUpBase: false,
  snapsAtaqueVinculados: 0,
  ultimoTotalSnapsPreenchidos: 0,
  posicoesAnteriores: new Map<string, Vetor3>(),
  ocupado: false,
};

// ============================================================================
// 3. ADAPTADOR PARA A API REAL DO DICEYTABLE
// ============================================================================

function lerVetor(pos: any): Vetor3 {
  if (Array.isArray(pos)) {
    return [Number(pos[0] ?? 0), Number(pos[1] ?? ALTURA_MESA), Number(pos[2] ?? 0)];
  }
  if (pos && typeof pos === "object") {
    return [Number(pos.x ?? 0), Number(pos.y ?? ALTURA_MESA), Number(pos.z ?? 0)];
  }
  return [0, ALTURA_MESA, 0];
}

async function pausaFisica(segundos = 0.06): Promise<boolean> {
  const w = world as any;
  if (typeof w.wait === "function") {
    await w.wait(segundos);
    return true;
  }
  const timer = (globalThis as any).setTimeout;
  if (typeof timer === "function") {
    await new Promise<void>((resolve) =>
      timer(resolve, Math.max(15, Math.round(segundos * 1000)))
    );
    return true;
  }
  return false;
}

function encontrarSnapDisponivel(
  snapPoints: any[],
  usados: Set<any>,
  coordenadaBase: Vetor3,
  nomeOpcional?: string,
  raioMax = 0.3
): any | null {
  if (nomeOpcional) {
    const porNome = snapPoints.find(
      (sp: any) =>
        !usados.has(sp) &&
        String(sp?.name ?? "").trim().toLowerCase() === nomeOpcional.toLowerCase()
    );
    if (porNome) return porNome;
  }

  const [bx, , bz] = coordenadaBase;
  let maisProximo: any = null;
  let menorDist = raioMax;

  for (const sp of snapPoints) {
    if (usados.has(sp)) continue;
    const [sx, , sz] = lerVetor(sp.position ?? sp);
    const dist = Math.hypot(sx - bx, sz - bz);
    if (dist < menorDist) {
      menorDist = dist;
      maisProximo = sp;
    }
  }

  return maisProximo;
}

// Vincula automaticamente as zonas da mesa e os 3 Snap Points de ataque do Editor
async function sincronizarComSnapPoints() {
  const snapPoints: any[] = (await world.getSnapPoints?.()) ?? [];
  if (snapPoints.length === 0) return;

  const usados = new Set<any>();

  // 1. Vincula primeiro os 7 pontos centrais e o descarte
  for (const chave of Object.keys(POSICOES_BASE)) {
    const sp = encontrarSnapDisponivel(snapPoints, usados, POSICOES_BASE[chave], chave, 0.25);
    if (sp) {
      usados.add(sp);
      POSICOES_MESA[chave] = lerVetor(sp.position ?? sp);
    }
  }

  // 2. Vincula os 3 Snap Points restantes aos 3 jogadores
  let vinculados = 0;
  for (const jogador of JOGADORES_MESA) {
    const spAtaque = encontrarSnapDisponivel(
      snapPoints,
      usados,
      jogador.pontoAtaque,
      jogador.nomeSnapAtaque,
      5.0
    );
    if (spAtaque) {
      usados.add(spAtaque);
      jogador.pontoAtaque = lerVetor(spAtaque.position ?? spAtaque);
      vinculados++;
    }
  }

  estado.snapsAtaqueVinculados = vinculados;
}

async function listarTodosObjetos(): Promise<any[]> {
  const objetos: any[] = await world.getAllObjects();
  return objetos ?? [];
}

async function obterObjetoPorNome(nome: string): Promise<any> {
  const todos = await listarTodosObjetos();
  return todos.find((obj: any) => obj?.name === nome) ?? null;
}

function dentroDaArea(posObj: any, centro: Vetor3, raioX = RAIO_DETECCAO, raioZ = RAIO_DETECCAO): boolean {
  const [ox, , oz] = lerVetor(posObj);
  const [cx, , cz] = centro;
  return Math.abs(ox - cx) <= raioX && Math.abs(oz - cz) <= raioZ;
}

// Verifica se a carta foi realmente solta (não está sendo segurada, suspensa no ar nem em movimento)
function estaCartaAssentada(obj: any, centro: Vetor3): boolean {
  if (!obj) return false;

  // 1. Ignora se a engine indicar que algum jogador está segurando o objeto
  if (obj.isHeld || obj.heldBy || obj.grabbedBy || obj.isDragging) {
    return false;
  }

  const [ox, oy, oz] = lerVetor(obj.position);
  const [, cy] = centro;

  // 2. Ignora cartas elevadas acima do tampo da mesa enquanto são arrastadas
  const tetoMesa = Math.max(cy, ALTURA_MESA) + 0.08;
  if (oy > tetoMesa) {
    return false;
  }

  // 3. Exige que a carta esteja parada desde a verificação anterior (já foi solta no ponto)
  const chaveId = String(obj.id ?? "");
  if (chaveId) {
    const posAnt = estado.posicoesAnteriores.get(chaveId);
    if (!posAnt) return false;

    const deslocamento = Math.hypot(ox - posAnt[0], oy - posAnt[1], oz - posAnt[2]);
    if (deslocamento > 0.008) {
      return false;
    }
  }

  return true;
}

function atualizarHistoricoPosicoes(objetos: any[]) {
  const proximoMapa = new Map<string, Vetor3>();
  for (const obj of objetos) {
    if (obj?.id) {
      proximoMapa.set(String(obj.id), lerVetor(obj.position));
    }
  }
  estado.posicoesAnteriores = proximoMapa;
}

// Retorna todos os objetos de carta/pilha na área (com opção de exigir que estejam soltos/assentados)
async function objetosNaArea(
  centro: Vetor3,
  raioX = RAIO_DETECCAO,
  raioZ = RAIO_DETECCAO,
  apenasAssentadas = false
): Promise<any[]> {
  const todos = await listarTodosObjetos();
  return todos.filter(
    (obj: any) =>
      obj &&
      obj.name !== "Deck_Ocorrencia" &&
      obj.name !== "Deck_Acao" &&
      dentroDaArea(obj.position, centro, raioX, raioZ) &&
      (!apenasAssentadas || estaCartaAssentada(obj, centro))
  );
}

// Retorna apenas cartas avulsas na área
async function cartasNaArea(
  centro: Vetor3,
  raioX = RAIO_DETECCAO,
  raioZ = RAIO_DETECCAO,
  apenasAssentadas = false
): Promise<any[]> {
  const objetos = await objetosNaArea(centro, raioX, raioZ, apenasAssentadas);
  return objetos.filter((obj: any) => (obj.stackCount ?? 1) <= 1);
}

function contarTotalCartas(objetos: any[]): number {
  return objetos.reduce((soma, obj) => soma + Number(obj?.stackCount ?? 1), 0);
}

async function cartasNaMaoVisivel(jogador: ConfigJogador): Promise<any[]> {
  return await cartasNaArea(jogador.centroMao, 0.36, 0.1, false);
}

async function moverCartaParaPonto(
  carta: any,
  destino: Vetor3,
  viradaParaCima: boolean,
  rotacaoY = 0,
  indicePilha = 0
) {
  if (!carta || !destino) return;

  // 1. Vira a carta primeiro e aguarda a animação de flip concluir
  if (viradaParaCima && carta.faceUp === false && typeof carta.flip === "function") {
    await carta.flip();
    await pausaFisica(0.22);
  } else if (!viradaParaCima && carta.faceUp === true && typeof carta.flip === "function") {
    await carta.flip();
    await pausaFisica(0.22);
  }

  if (typeof carta.refresh === "function") {
    await carta.refresh();
  }

  // 2. Normaliza a rotação para eliminar inversão de 180° quando o flip() gira pelo eixo X
  if (typeof carta.setRotation === "function") {
    const rotAtual = Array.isArray(carta.rotation) ? carta.rotation : [0, rotacaoY, 0];
    const rx = Number(rotAtual[0] ?? 0);
    const rz = Number(rotAtual[2] ?? 0);

    const virouPeloEixoX = Math.abs(rx) > 90;
    const rzNormalizado = virouPeloEixoX ? (Math.abs(rz) > 90 ? 0 : 180) : rz;

    await carta.setRotation([0, rotacaoY, rzNormalizado]);
  }

  // 3. Fixa a posição exata na mesa (com leve escalonamento vertical para pilhas)
  const ySeguro = Number((Math.max(destino[1], ALTURA_MESA) + indicePilha * 0.015).toFixed(3));

  if (typeof carta.setPosition === "function") {
    await carta.setPosition([destino[0], ySeguro, destino[2]]);
  }

  if (typeof carta.refresh === "function") {
    await carta.refresh();
  }

  await pausaFisica(0.05);
}

async function puxarCartaDoDeck(deck: any): Promise<any | null> {
  if (!deck) return null;
  if ((deck.stackCount ?? 0) <= 0) return null;

  let carta: any = null;
  if (typeof deck.drawCard === "function") {
    carta = await deck.drawCard();
  } else if (typeof deck.draw === "function") {
    const res = await deck.draw(1);
    carta = Array.isArray(res) ? res[0] : res;
  }

  if (carta && typeof carta.refresh === "function") {
    await carta.refresh();
  }
  return carta ?? null;
}

// Separa pilhas pequenas (quando múltiplas cartas foram colocadas no mesmo depósito) em cartas individuais
async function descompactarPilhas(objetos: any[]): Promise<any[]> {
  const individuais: any[] = [];
  for (const obj of objetos) {
    if (!obj) continue;
    while ((obj.stackCount ?? 1) > 1) {
      const extra = await puxarCartaDoDeck(obj);
      if (!extra) break;
      individuais.push(extra);
    }
    individuais.push(obj);
  }
  return individuais;
}

// ============================================================================
// 4. FLUXO DAS FASES (LOOP DA RODADA)
// ============================================================================

async function iniciarJogo() {
  if (estado.jogoIniciado) return;
  estado.jogoIniciado = true;
  estado.rodada = 1;
  estado.pontuacaoOculta = 0;

  await sincronizarComSnapPoints();

  const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
  const deckAcao = await obterObjetoPorNome("Deck_Acao");

  if (typeof deckOcorrencia?.shuffle === "function") await deckOcorrencia.shuffle();
  if (typeof deckAcao?.shuffle === "function") await deckAcao.shuffle();

  if (deckAcao) {
    estado.deckAcaoFaceUpBase = Boolean(deckAcao.faceUp);
  }

  await executarFase1();
  iniciarMonitoramentoContinuo();
}

// FASE 1: Garantir 3 cartas de ocorrência viradas para cima nos pontos configurados
async function executarFase1() {
  estado.faseAtual = "FASE_1";
  const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");

  for (let i = 1; i <= 3; i++) {
    const pontoOcorrencia = POSICOES_MESA[`Ocorrencia_${i}`];
    const cartasAtuais = await objetosNaArea(pontoOcorrencia, RAIO_DETECCAO, RAIO_DETECCAO, false);

    if (cartasAtuais.length === 0) {
      const novaCarta = await puxarCartaDoDeck(deckOcorrencia);
      if (novaCarta) {
        await moverCartaParaPonto(novaCarta, pontoOcorrencia, true, 0, 0);
      }
    }
  }

  await executarFase2();
}

// FASE 2: Garantir que cada um dos 3 jogadores tenha 4 cartas de ação visíveis à frente
async function executarFase2() {
  estado.faseAtual = "FASE_2";
  const deckAcao = await obterObjetoPorNome("Deck_Acao");

  for (const jogador of JOGADORES_MESA) {
    const iniciais = await cartasNaMaoVisivel(jogador);
    let qtdNaMao = iniciais.length;

    while (qtdNaMao < 4) {
      const cartaAcao = await puxarCartaDoDeck(deckAcao);
      if (!cartaAcao) break;

      const deslocamentoX = (qtdNaMao - 1.5) * 0.16;
      const destinoCarta: Vetor3 = [
        Number((jogador.centroMao[0] + deslocamentoX).toFixed(3)),
        ALTURA_MESA,
        jogador.centroMao[2],
      ];

      await moverCartaParaPonto(cartaAcao, destinoCarta, true, jogador.rotacaoY, 0);
      qtdNaMao++;
    }
  }

  iniciarFase3();
}

// FASE 3: Cada jogador coloca 1 carta de ação no seu Snap Point de Ataque
function iniciarFase3() {
  estado.faseAtual = "FASE_3";
  estado.cartasAtaqueDaRodada.clear();
  estado.ultimoTotalSnapsPreenchidos = 0;

  world.broadcast(
    `Rodada ${estado.rodada} — Fase 3: Solte 1 carta em cada Snap Point de Ataque e aperte F sobre o Deck_Acao para ir à Fase 4.`
  );
}

// Vira automaticamente para baixo apenas quando a carta já foi solta e assentou no Snap Point
async function prepararCartasNosSnapPointsDeAtaque() {
  if (estado.faseAtual !== "FASE_3") return;

  let preenchidos = 0;

  for (const jogador of JOGADORES_MESA) {
    const cartas = await cartasNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, true);
    if (cartas.length === 1) {
      preenchidos++;
      if (cartas[0].faceUp === true && typeof cartas[0].flip === "function") {
        await cartas[0].flip();
        await pausaFisica(0.2);
      }
    }
  }

  if (preenchidos !== estado.ultimoTotalSnapsPreenchidos) {
    estado.ultimoTotalSnapsPreenchidos = preenchidos;
    if (preenchidos === 3) {
      world.broadcast(
        "Snap Points de Ataque: 3/3 prontos! Aperte F sobre o Deck_Acao para revelar as cartas e ir para a Fase 4."
      );
    } else if (preenchidos > 0) {
      world.broadcast(`Snap Points de Ataque preenchidos: ${preenchidos}/3.`);
    }
  }
}

// Valida se todos os 3 Snap Points possuem 1 carta solta, desvira todas para cima e inicia a Fase 4
async function validarEAvancarParaFase4() {
  if (estado.faseAtual !== "FASE_3") return;

  const selecionadas: { carta: any; jogador: ConfigJogador }[] = [];
  const pendentes: string[] = [];

  for (const jogador of JOGADORES_MESA) {
    const objetos = await objetosNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, true);
    const total = contarTotalCartas(objetos);

    if (total === 0) {
      pendentes.push(`${jogador.nome} (sem carta solta)`);
      continue;
    }

    if (total > 1) {
      pendentes.push(`${jogador.nome} (mais de 1 carta)`);
      continue;
    }

    selecionadas.push({ carta: objetos[0], jogador });
  }

  if (pendentes.length > 0) {
    world.broadcast(
      `Não foi possível avançar para a Fase 4. Verifique os Snap Points: ${pendentes.join(", ")}.`
    );
    return;
  }

  // Revela (vira para cima) todas as 3 cartas de ataque escolhidas na rodada
  estado.cartasAtaqueDaRodada.clear();
  for (const { carta, jogador } of selecionadas) {
    await moverCartaParaPonto(carta, jogador.pontoAtaque, true, jogador.rotacaoY, 0);
    if (carta.id) {
      estado.cartasAtaqueDaRodada.add(String(carta.id));
    }
  }

  iniciarFase4();
}

// FASE 4: Jogadores movem livremente todas as cartas de Ataque para os 3 depósitos
function iniciarFase4() {
  estado.faseAtual = "FASE_4";
  world.broadcast(
    "Fase 4: Cartas de Ataque reveladas! Aloquem todas elas nos 3 Depósitos à frente das Ocorrências."
  );
}

async function verificarConclusaoFase4() {
  if (estado.faseAtual !== "FASE_4") return;

  const totalEsperado = estado.cartasAtaqueDaRodada.size;
  if (totalEsperado === 0) return;

  // Garante que nenhuma carta ficou parada nos Snap Points de Ataque
  for (const jogador of JOGADORES_MESA) {
    const sobras = await objetosNaArea(jogador.pontoAtaque, RAIO_DETECCAO, RAIO_DETECCAO, false);
    if (sobras.length > 0) {
      return;
    }
  }

  // Soma apenas cartas já soltas e assentadas nos 3 Depósitos (ignora cartas passando por cima)
  let totalDepositado = 0;
  for (let i = 1; i <= 3; i++) {
    const pontoDeposito = POSICOES_MESA[`Deposito_${i}`];
    const objetosNoDeposito = await objetosNaArea(
      pontoDeposito,
      RAIO_DETECCAO,
      RAIO_DETECCAO,
      true
    );
    totalDepositado += contarTotalCartas(objetosNoDeposito);
  }

  if (totalDepositado >= totalEsperado) {
    await executarFase5();
  }
}

// FASE 5: Resolver a ocorrência com mais cartas de ataque, descartar, pontuar oculto e reiniciar loop
async function executarFase5() {
  estado.faseAtual = "FASE_5";

  let indiceVencedor = 1;
  let maiorQtdAtaques = -1;

  for (let i = 1; i <= 3; i++) {
    const pontoDeposito = POSICOES_MESA[`Deposito_${i}`];
    const objetos = await objetosNaArea(pontoDeposito, RAIO_DETECCAO, RAIO_DETECCAO, false);
    const qtdCartas = contarTotalCartas(objetos);
    if (qtdCartas > maiorQtdAtaques) {
      maiorQtdAtaques = qtdCartas;
      indiceVencedor = i;
    }
  }

  world.broadcast(
    `Fase 5: Resolvendo Ocorrência ${indiceVencedor} (${maiorQtdAtaques} carta(s) de ataque)!`
  );

  const pontoOcorrenciaVencedora = POSICOES_MESA[`Ocorrencia_${indiceVencedor}`];
  const pontoDepositoVencedor = POSICOES_MESA[`Deposito_${indiceVencedor}`];
  const pontoDescarte = POSICOES_MESA.Zona_Descarte;

  const objOcorrencia = await objetosNaArea(
    pontoOcorrenciaVencedora,
    RAIO_DETECCAO,
    RAIO_DETECCAO,
    false
  );
  const objAtaque = await objetosNaArea(
    pontoDepositoVencedor,
    RAIO_DETECCAO,
    RAIO_DETECCAO,
    false
  );

  const cartasOcorrencia = await descompactarPilhas(objOcorrencia);
  const cartasAtaque = await descompactarPilhas(objAtaque);
  const cartaOcorrenciaResolvida = cartasOcorrencia[0] ?? null;

  if (cartaOcorrenciaResolvida) {
    const pontosGanhos = calcularPontuacao(cartaOcorrenciaResolvida, cartasAtaque);
    estado.pontuacaoOculta += pontosGanhos;
  }

  const objDescarte = await objetosNaArea(pontoDescarte, RAIO_DETECCAO, RAIO_DETECCAO, false);
  let qtdNoDescarte = contarTotalCartas(objDescarte);

  for (const carta of cartasOcorrencia) {
    await moverCartaParaPonto(carta, pontoDescarte, true, 0, qtdNoDescarte++);
  }
  for (const carta of cartasAtaque) {
    await moverCartaParaPonto(carta, pontoDescarte, true, 0, qtdNoDescarte++);
  }

  const deckOcorrencia = await obterObjetoPorNome("Deck_Ocorrencia");
  const restamNoDeck = (deckOcorrencia?.stackCount ?? 0) > 0;

  let restamNaMesa = false;
  for (let i = 1; i <= 3; i++) {
    const cartas = await objetosNaArea(
      POSICOES_MESA[`Ocorrencia_${i}`],
      RAIO_DETECCAO,
      RAIO_DETECCAO,
      false
    );
    if (cartas.length > 0) {
      restamNaMesa = true;
      break;
    }
  }

  if (restamNoDeck || restamNaMesa) {
    estado.rodada++;
    await executarFase1();
  } else {
    estado.faseAtual = "FIM_DE_JOGO";
    world.broadcast("Fim de jogo! Todas as ocorrências foram resolvidas.");
  }
}

// ============================================================================
// 5. CÁLCULO DE PONTUAÇÃO (Preencheremos com a sua regra na próxima etapa)
// ============================================================================

function calcularPontuacao(cartaOcorrencia: any, cartasAtaque: any[]): number {
  return 0;
}

// ============================================================================
// 6. MONITORAMENTO CONTÍNUO DA MESA
// ============================================================================

