    const todosIniciais = await listarTodosObjetos();
    atualizarHistoricoPosicoes(todosIniciais);
    while (estado.faseAtual !== "FIM_DE_JOGO") {
        const pausou = await pausaFisica(0.4);
        if (!pausou)
            break;
        await processarComLock(async () => {
            if (estado.faseAtual === "FASE_3") {
                await prepararCartasNosSnapPointsDeAtaque();
                // Verifica se o jogador apertou F (Flip) sobre o Deck_Acao para confirmar a Fase 4
                const deckAcao = await obterObjetoPorNome("Deck_Acao");
                if (deckAcao && Boolean(deckAcao.faceUp) !== estado.deckAcaoFaceUpBase) {
                    if (typeof deckAcao.flip === "function") {
                        await deckAcao.flip();
                        await pausaFisica(0.25);
                    }
                    estado.deckAcaoFaceUpBase = Boolean(deckAcao.faceUp);
                    await validarEAvancarParaFase4();
                }
            }
            else if (estado.faseAtual === "FASE_4") {
                await verificarConclusaoFase4();
            }
            const todosAtuais = await listarTodosObjetos();
            atualizarHistoricoPosicoes(todosAtuais);
        });
    }
}
